public sealed class OrderProcessor(
    IServiceScopeFactory scopeFactory,
    ILogger<OrderProcessor> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var message in ReadQueueAsync(stoppingToken))
        {
            // ONE scope per message — not one for the whole service
            await using var scope = scopeFactory.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var notifier = scope.ServiceProvider.GetRequiredService<IOrderNotifier>();

            var order = await db.Orders.FindAsync([message.OrderId], stoppingToken);
            if (order is null) continue;

            order.Status = OrderStatus.Processed;
            await db.SaveChangesAsync(stoppingToken);
            await notifier.SendConfirmationAsync(order, stoppingToken);
            // scope disposed — DbContext released
        }
    }
}

public sealed class OutboxDispatcher(IServiceScopeFactory scopes) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await using var scope = scopes.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var publisher = scope.ServiceProvider.GetRequiredService<IEventPublisher>();

            var batch = await db.OutboxMessages
                .Where(m => m.ProcessedAt == null)
                .OrderBy(m => m.CreatedAt)
                .Take(20)
                .ToListAsync(ct);

            foreach (var msg in batch)
            {
                await publisher.PublishAsync(msg.Payload, ct);
                msg.ProcessedAt = DateTimeOffset.UtcNow;
            }
            await db.SaveChangesAsync(ct);
            await Task.Delay(TimeSpan.FromSeconds(5), ct);
        }
    }
}

public sealed class CacheRefreshService(
    IServiceScopeFactory scopes,
    ILogger<CacheRefreshService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromMinutes(5));
        while (await timer.WaitForNextTickAsync(ct))
        {
            try
            {
                await using var scope = scopes.CreateAsyncScope();
                var refresher = scope.ServiceProvider
                    .GetRequiredService<ICacheRefresher>();
                await refresher.RefreshAsync(ct);
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Cache refresh failed");
            }
        }
    }
}

