public sealed class BadWorker(IServiceScopeFactory scopes) : BackgroundService
{
    private readonly IServiceScope _scope = scopes.CreateScope(); // NEVER

    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        var db = _scope.ServiceProvider.GetRequiredService<AppDbContext>();
        while (!ct.IsCancellationRequested)
        {
            // Same DbContext forever — change tracker grows, memory leaks
            var items = await db.QueueItems.ToListAsync(ct);
            // ...
        }
    }
    // _scope never disposed until app shutdown
}

